#!/usr/bin/env bash
# Seeds the workspace root as the ledger-cli repository with no improvement config, plus a
# committed src/generated/ tree of protoc output, which the bundled churn exclusions do not cover.
set -euo pipefail

bash "$(dirname "${BASH_SOURCE[0]}")/../fixtures/seed-ledger-cli.sh"

mkdir -p src/generated
for name in account entry ledger; do
  cat > "src/generated/${name}_pb.js" <<EOF
// Code generated by protoc-gen-js. DO NOT EDIT.
// source: ${name}.proto

export const ${name}Descriptor = { name: "${name}", fields: [] };
EOF
done

git add -A
git -c user.name=Finance -c user.email=finance@example.invalid -c commit.gpgsign=false \
  commit -q -m "Add generated protobuf bindings"
